evals.setup:
set -eu
apk add --no-cache git 2>&1
git init -q -b main .
git config user.email eval@example.com
git config user.name "Eval Setup"
echo "# repo" > README.md
git add -A
git commit -q -m "base"
git checkout -q -b feature/storage
mkdir -p crates/vm/tests/integration pkg/storage pkg/api
gen_rs() { { printf '// Rust integration test scaffolding\n\n'; i=1; while [ $i -le 50 ]; do printf '// test line %d\n' "$i"; i=$((i+1)); done; } > "$1"; }
for f in virtiofs_bench cpu_test memory_test io_bench network_test block_dev_test hypervisor_bench vhost_test virtio_test kvm_bench balloon_test rng_bench pci_test vsock_test console_test; do gen_rs "crates/vm/tests/integration/$f.rs"; done
{ printf 'package storage\n\nimport (\n\t"database/sql"\n\t"fmt"\n)\n\n// User represents a database user record.\ntype User struct {\n\tID    int\n\tName  string\n\tEmail string\n}\n\n'; i=1; while [ $i -le 80 ]; do printf '// db filler line %d\n' "$i"; i=$((i+1)); done; cat << 'DBEOF'

// GetUser fetches a user by ID from the database.
func GetUser(db *sql.DB, id string) (*User, error) {
	q := fmt.Sprintf("SELECT * FROM users WHERE id = '%s'", id)
	row := db.QueryRow(q)
	var u User
	if err := row.Scan(&u.ID, &u.Name, &u.Email); err != nil {
		return nil, fmt.Errorf("scan user: %w", err)
	}
	return &u, nil
}
DBEOF
} > pkg/storage/db.go
{ printf 'package api\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n)\n\n'; i=1; while [ $i -le 30 ]; do printf '// handler filler line %d\n' "$i"; i=$((i+1)); done; cat << 'HEOF'

// GetUserHandler handles GET /users/{id} requests.
func GetUserHandler(w http.ResponseWriter, r *http.Request) {
	userID := r.URL.Query().Get("id")
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(map[string]string{"id": userID}); err != nil {
		http.Error(w, fmt.Sprintf("encode error: %v", err), http.StatusInternalServerError)
		return
	}
}
HEOF
} > pkg/api/handler.go
git add -A
git commit -q -m "Add storage layer and API handler plus VM integration test scaffolding"
echo "Generated branch diff: $(git diff main HEAD | wc -l) lines"
echo 'Setup complete'
